-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the seismolord capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: some graded figure(s) printed; section 3 pick B (strip)
-- advanced: some graded figure(s) printed; section 3 pick B (strip)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update takes them out
--   of the lessons and panels.
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- seismolord / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book seismolord refused: seismolord/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '0ce29aaca9435b8f2cbbd9ab65bfede5' and fields = '[{"key": "mean_velocity_ms", "tol": 1, "unit": "m/s", "label": "Mean sonic velocity", "expected": 3145.2869374221345}, {"key": "twt_at_log_top_ms", "tol": 0.5, "unit": "ms", "label": "TWT at the top of the log", "expected": 1500}, {"key": "imp_max", "tol": 10, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance", "expected": 10624.9560546875}, {"key": "rc_peak_abs", "tol": 0.0005, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.017688043415546417}, {"key": "rc_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1582}, {"key": "syn_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (25 Hz)", "expected": 1642}]'::jsonb then 'old'
              when md5(prompt) = 'c81a13bbfe68c6f97d4f66f5903ea57b' and fields = '[{"key": "mean_velocity_ms", "tol": 1, "unit": "m/s", "label": "Mean sonic velocity", "expected": 3145.2869374221345}, {"key": "twt_at_log_top_ms", "tol": 0.5, "unit": "ms", "label": "TWT at the top of the log", "expected": 1500}, {"key": "imp_max", "tol": 10, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance", "expected": 10624.9560546875}, {"key": "rc_peak_abs", "tol": 0.0005, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.017688043415546417}, {"key": "rc_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1582}, {"key": "syn_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (25 Hz)", "expected": 1642}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'seismolord' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book seismolord refused: seismolord/beginner matches neither its published form (prompt md5 0ce29aaca9435b8f2cbbd9ab65bfede5) nor its W1 form (prompt md5 c81a13bbfe68c6f97d4f66f5903ea57b), with the fields this file was generated against';
  end if;

  -- seismolord / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book seismolord refused: seismolord/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '09e39aaf8a6acb6b7b71f47935ec9571' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb then 'old'
              when md5(prompt) = '0586befbe8a90da6228d5b53750c46fb' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book seismolord refused: seismolord/intermediate matches neither its published form (prompt md5 09e39aaf8a6acb6b7b71f47935ec9571) nor its W1 form (prompt md5 0586befbe8a90da6228d5b53750c46fb), with the fields this file was generated against';
  end if;

  -- seismolord / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book seismolord refused: seismolord/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e17e1dac9c11bcfa899daa4fbe875920' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb then 'old'
              when md5(prompt) = '4ccfcca366426ba684682830d039ffe0' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book seismolord refused: seismolord/advanced matches neither its published form (prompt md5 e17e1dac9c11bcfa899daa4fbe875920) nor its W1 form (prompt md5 4ccfcca366426ba684682830d039ffe0), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book seismolord: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book seismolord refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Set the wavelet to 25 Hz and read the synthetic summary panel: report the mean sonic velocity, the two-way time at the top of the log under the teaching time-depth function, the maximum impedance, and the strongest reflection coefficient and synthetic amplitude with their two-way times.',
           fields = '[{"key": "mean_velocity_ms", "tol": 1, "unit": "m/s", "label": "Mean sonic velocity", "expected": 3145.2869374221345}, {"key": "twt_at_log_top_ms", "tol": 0.5, "unit": "ms", "label": "TWT at the top of the log", "expected": 1500}, {"key": "imp_max", "tol": 10, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance", "expected": 10624.9560546875}, {"key": "rc_peak_abs", "tol": 0.0005, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.017688043415546417}, {"key": "rc_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1582}, {"key": "syn_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (25 Hz)", "expected": 1642}]'::jsonb
     where app_slug = 'seismolord' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book seismolord refused: seismolord/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'c81a13bbfe68c6f97d4f66f5903ea57b' and fields = '[{"key": "mean_velocity_ms", "tol": 1, "unit": "m/s", "label": "Mean sonic velocity", "expected": 3145.2869374221345}, {"key": "twt_at_log_top_ms", "tol": 0.5, "unit": "ms", "label": "TWT at the top of the log", "expected": 1500}, {"key": "imp_max", "tol": 10, "unit": "(m/s)·(g/cc)", "label": "Maximum impedance", "expected": 10624.9560546875}, {"key": "rc_peak_abs", "tol": 0.0005, "unit": "-", "label": "Strongest reflection coefficient (abs)", "expected": 0.017688043415546417}, {"key": "rc_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest reflection", "expected": 1582}, {"key": "syn_peak_twt_ms", "tol": 2, "unit": "ms", "label": "TWT of the strongest synthetic amplitude (25 Hz)", "expected": 1642}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book seismolord refused: seismolord/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. The observed seismic trace is the 25 Hz synthetic arriving late by a lag this brief does not state. Run the bulk-shift scan and read the panel: the suggested shift, and the correlation at zero lag, which is what the tie scores if you never shift it. Then flip the wavelet between 15 and 40 Hz and report the strongest synthetic amplitude and its time at each frequency. Tuning moves both.',
           fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb
     where app_slug = 'seismolord' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book seismolord refused: seismolord/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '0586befbe8a90da6228d5b53750c46fb' and fields = '[{"key": "bulk_shift_ms", "tol": 0.5, "unit": "ms", "label": "Suggested bulk shift", "expected": 8}, {"key": "corr_zero_lag", "tol": 0.0005, "unit": "-", "label": "Correlation at zero lag, before any shift", "expected": 0.6217418028775199}, {"key": "peak15_abs", "tol": 0.002, "unit": "-", "label": "Strongest synthetic amplitude at 15 Hz", "expected": 0.1573149710893631}, {"key": "peak40_abs", "tol": 0.001, "unit": "-", "label": "Strongest synthetic amplitude at 40 Hz", "expected": 0.0362229160964489}, {"key": "peak15_twt", "tol": 2, "unit": "ms", "label": "TWT of the 15 Hz peak", "expected": 1580}, {"key": "peak40_twt", "tol": 2, "unit": "ms", "label": "TWT of the 40 Hz peak", "expected": 1646}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book seismolord refused: seismolord/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Model the SAND top and base as an equal and opposite reflection pair (RC +0.08 / -0.08) in a wedge from 0 to 60 ms at a 2 ms sample rate. Read the tuning panel at 25 Hz and 40 Hz: the tuning thickness at each frequency, the peak amplitude at 25 Hz tuning, the amplitude of a 6 ms bed at 40 Hz, the ratio of the 25 Hz tuning amplitude to the isolated-reflector level on the thick end of the same run, and the Kallweit-Wood theoretical tuning thickness sqrt(6)/(2*pi*f) at 25 Hz.',
           fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb
     where app_slug = 'seismolord' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book seismolord refused: seismolord/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '4ccfcca366426ba684682830d039ffe0' and fields = '[{"key": "tune25_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 25 Hz", "expected": 16}, {"key": "tune25_amp", "tol": 0.002, "unit": "-", "label": "Peak amplitude at 25 Hz tuning", "expected": 0.1155947595834732}, {"key": "tune40_ms", "tol": 0, "unit": "ms", "label": "Tuning thickness at 40 Hz", "expected": 10}, {"key": "amp40_at_6ms", "tol": 0.0005, "unit": "-", "label": "Amplitude of a 6 ms bed at 40 Hz", "expected": 0.09535394608974457}, {"key": "tune25_iso_ratio", "tol": 0.001, "unit": "-", "label": "Tuning amplitude over the isolated level at 25 Hz", "expected": 1.4449345270902185}, {"key": "theory25_ms", "tol": 0.05, "unit": "ms", "label": "Theoretical tuning thickness at 25 Hz", "expected": 15.593936024673521}]'::jsonb) from public.academy_capstones where app_slug = 'seismolord' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book seismolord refused: seismolord/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book seismolord: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
